import{_ as e}from"./chunks/folders.9ioZn9MV.js";import{_ as t,c as r,o,a2 as i}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"比較資料夾","description":"一次看全新增、修改與缺失的檔案，按狀態篩選，並讓兩邊恢復一致。","frontmatter":{"title":"比較資料夾","description":"一次看全新增、修改與缺失的檔案，按狀態篩選，並讓兩邊恢復一致。"},"headers":[],"relativePath":"zh-TW/guide/folders.md","filePath":"zh-TW/guide/folders.md","lastUpdated":1793948370000}'),s={name:"zh-TW/guide/folders.md"};function l(n,a,d,c,h,p){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="比較資料夾" tabindex="-1">比較資料夾 <a class="header-anchor" href="#比較資料夾" aria-label="Permalink to &quot;比較資料夾&quot;">​</a></h1><p>兩個本該一致的資料夾 —— 工作副本和備份、舊匯出和新匯出 —— 逐個檔案去對， 實在太累。qDiff 把整棵樹一次擺出來。</p><img src="'+e+'" alt="兩列資料夾樹，檔案狀態用顏色區分" class="guide-shot"><h2 id="打開兩個資料夾" tabindex="-1">打開兩個資料夾 <a class="header-anchor" href="#打開兩個資料夾" aria-label="Permalink to &quot;打開兩個資料夾&quot;">​</a></h2><p>把兩個資料夾拖進視窗，或者從「檔案 → 開啟」裡選。裡面的子資料夾也會一起比， 看到的是完整全貌。</p><h2 id="一眼讀懂這棵樹" tabindex="-1">一眼讀懂這棵樹 <a class="header-anchor" href="#一眼讀懂這棵樹" aria-label="Permalink to &quot;一眼讀懂這棵樹&quot;">​</a></h2><ul><li><strong>綠色</strong> —— 只有一邊有這個檔案。</li><li><strong>橙色</strong> —— 名字一樣，內容不一樣。</li><li><strong>紅色</strong> —— 另一邊少了這個檔案。</li><li><strong>灰色</strong> —— 兩邊一致。</li></ul><h2 id="只看想看的" tabindex="-1">只看想看的 <a class="header-anchor" href="#只看想看的" aria-label="Permalink to &quot;只看想看的&quot;">​</a></h2><p>用狀態篩選把已經一致的檔案藏起來，也可以輸入名稱的一部分來縮小範圍。 可以只核對檔名，也可以連內容一起核對 —— 備份看起來齊全、裡面卻是舊內容時， 特別有用。</p><p>資料夾再大也能很快出結果，不用盯著進度條等。</p><h2 id="在列表裡順手整理" tabindex="-1">在列表裡順手整理 <a class="header-anchor" href="#在列表裡順手整理" aria-label="Permalink to &quot;在列表裡順手整理&quot;">​</a></h2><p>把檔案複製到另一邊、刪掉多餘的、或讓一組檔案同步一致，都在這棵樹裡完成， 不用切回 Finder。</p><div class="tip custom-block"><p class="custom-block-title">放心先看看</p><p>在你主動選擇某個操作之前，磁碟上的內容不會有任何改動。單純瀏覽、篩選比較 是完全安全的。</p></div><p>接下來：<a href="./projects.html">提交前把專案看一遍</a>。</p>',14)])])}const m=t(s,[["render",l]]);export{f as __pageData,m as default};
